function bg(el){let e=el;let layers=[];while(e&&e.nodeType===1){const c=parse(getComputedStyle(e).backgroundColor);if(c&&(c.length<4||c[3]>0)){layers.push(c);if(c.length<4||c[3]===1)break;}e=e.parentElement}let base=[255,255,255];for(let i=layers.length-1;i>=0;i--){const c=layers[i];const a=c.length>3?c[3]:1;base=base.map((v,j)=>v*(1-a)+c[j]*a)}return base}
const out=[];
const els=[...document.querySelectorAll('#root *')].filter(e=>[...e.childNodes].some(n=>n.nodeType===3&&n.textContent.trim()));
